type Row = { card_id: string; level: number; due_at: number; last_seen: number; seen: number; wrong: number; updated_at: number };

// ---------- helpers ----------
function cors(origin: string | null): Record<string, string> {
  if (origin !== ALLOWED_ORIGIN) return {};
  return {
    "Access-Control-Allow-Origin": ALLOWED_ORIGIN,
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Authorization, Content-Type",
    "Access-Control-Max-Age": "86400",
    "Vary": "Origin",
  };
}
function json(data: unknown, status = 200, extra: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(data), { status, headers: { "Content-Type": "application/json", ...extra } });
}
async function sha256hex(s: string): Promise<string> {
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(d)].map(b => b.toString(16).padStart(2, "0")).join("");
}
function randomToken(): string {
  const b = crypto.getRandomValues(new Uint8Array(32));
  return btoa(String.fromCharCode(...b)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function bearer(req: Request): string | null {
  const m = (req.headers.get("Authorization") || "").match(/^Bearer\s+(\S+)$/i);
  return m ? m[1] : null;
}
async function authUser(env: Env, req: Request, kind: "write" | "read"): Promise<string | null> {
  const t = bearer(req);
  if (!t || t.length > 200) return null;
  const h = await sha256hex(t);
  const col = kind === "write" ? "token_hash" : "read_token_hash";
  const r = await env.DB.prepare(`SELECT id FROM users WHERE ${col} = ?`).bind(h).first<{ id: string }>();
  return r ? r.id : null;
}
const int = (v: unknown): number => { const n = Math.floor(Number(v)); return Number.isFinite(n) && n >= 0 ? n : 0; };

function normChange(cardId: string, c: any): Row | null {
  if (!CARD_ID_RE.test(cardId) || !c || typeof c !== "object") return null;
  return { card_id: cardId, level: Math.min(int(c.level), 100), due_at: int(c.due_at), last_seen: int(c.last_seen),
    seen: int(c.seen), wrong: int(c.wrong), updated_at: int(c.updated_at) };
}

async function getProgress(env: Env, userId: string): Promise<Record<string, Omit<Row, "card_id">>> {
  const { results } = await env.DB.prepare(
    "SELECT card_id, level, due_at, last_seen, seen, wrong, updated_at FROM progress WHERE user_id = ?").bind(userId).all<Row>();
  const out: Record<string, Omit<Row, "card_id">> = {};
  for (const { card_id, ...rest } of results) out[card_id] = rest;
  return out;
}

// changes: either {card_id: {...}} or [{card_id, ...}]; events: [{card_id, ok, ts}]
async function applySync(env: Env, userId: string, body: any): Promise<{ applied: number; events: number }> {
  const raw = body?.changes ?? {};
  const entries: [string, any][] = Array.isArray(raw) ? raw.map((c: any) => [String(c?.card_id), c]) : Object.entries(raw);
  const rawEv: any[] = Array.isArray(body?.events) ? body.events : [];
  if (entries.length > MAX_CHANGES || rawEv.length > MAX_EVENTS) throw new HttpError(413, "too many changes/events");
  const stmts: D1PreparedStatement[] = [];
  const up = env.DB.prepare(
    `INSERT INTO progress (user_id, card_id, level, due_at, last_seen, seen, wrong, updated_at)
     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)
     ON CONFLICT(user_id, card_id) DO UPDATE SET level=excluded.level, due_at=excluded.due_at,
       last_seen=excluded.last_seen, seen=excluded.seen, wrong=excluded.wrong, updated_at=excluded.updated_at
     WHERE excluded.updated_at > progress.updated_at`);
  for (const [id, c] of entries) {
    const r = normChange(id, c);
    if (r) stmts.push(up.bind(userId, r.card_id, r.level, r.due_at, r.last_seen, r.seen, r.wrong, r.updated_at));
  }
  const n = stmts.length;
  const ev = env.DB.prepare("INSERT INTO events (user_id, card_id, type, ok, data, ts) VALUES (?, ?, ?, ?, ?, ?)");
  let ne = 0;
  for (const e of rawEv) {
    const type = String(e?.type ?? (e && "ok" in e ? "answer" : ""));
    if (!EVENT_TYPES.has(type)) continue;
    const id = e?.card_id == null ? null : String(e.card_id);
    if (id !== null && !CARD_ID_RE.test(id)) continue;
    let data: string | null = null;
    if (e.data != null) { data = JSON.stringify(e.data); if (data.length > 500) data = null; }
    const ok = type === "answer" ? (e.ok ? 1 : 0) : null;
    stmts.push(ev.bind(userId, id, type, ok, data, int(e.ts) || Date.now())); ne++;
  }
  if (stmts.length) await env.DB.batch(stmts);
  return { applied: n, events: ne };
}

class HttpError extends Error { constructor(public status: number, msg: string) { super(msg); } }

// ---------- MCP (Streamable HTTP, stateless, JSON responses) ----------
const PROTOCOL_VERSIONS = ["2025-06-18", "2025-03-26", "2024-11-05"];
const TOOLS = [
  { name: "get_summary", description: "Overall learning summary: cards total/seen/known/due, accuracy over the last 7 days, streak info.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false } },
  { name: "get_struggling", description: "Cards the learner gets wrong most often (by wrong count, then low level).",
    inputSchema: { type: "object", properties: { limit: { type: "integer", minimum: 1, maximum: 100, default: 10 } }, additionalProperties: false } },
  { name: "get_due_cards", description: "Cards whose review is due now (seen cards with due_at <= now), plus count of never-seen cards.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false } },
  { name: "get_current_session", description: "The most recent study session (events separated by gaps < 30 min): every flip/answer/position event with card word+translation, current card, duration, answers right/wrong. Use to see live activity.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false } },
  { name: "get_recent_activity", description: "Answer events per day over the last N days, with accuracy and the cards reviewed.",
    inputSchema: { type: "object", properties: { days: { type: "integer", minimum: 1, maximum: 90, default: 7 } }, additionalProperties: false } },
];

function cardView(r: Row, now: number) {
  const m = CARD_META[r.card_id];
  return { card_id: r.card_id, dutch: m?.[0] ?? null, russian: m?.[1] ?? null, topic: m?.[2] ?? null,
    level: r.level, seen: r.seen, wrong: r.wrong, due_at: new Date(r.due_at).toISOString(), due_now: r.due_at <= now,
    last_seen: r.last_seen ? new Date(r.last_seen).toISOString() : null };
}
async function rows(env: Env, userId: string): Promise<Row[]> {
  const { results } = await env.DB.prepare(
    "SELECT card_id, level, due_at, last_seen, seen, wrong, updated_at FROM progress WHERE user_id = ?").bind(userId).all<Row>();
  return results;
}

async function callTool(env: Env, userId: string, name: string, args: any): Promise<unknown> {
  const now = Date.now();
  switch (name) {
    case "get_summary": {
      const rs = (await rows(env, userId)).filter(r => r.seen > 0);
      const total = Object.keys(CARD_META).length;
      const since = now - 7 * 864e5;
      const ev = await env.DB.prepare("SELECT COUNT(*) AS n, COALESCE(SUM(ok),0) AS ok, MAX(ts) AS last FROM events WHERE user_id = ? AND ts >= ? AND type = 'answer'")
        .bind(userId, since).first<{ n: number; ok: number; last: number | null }>();
      const days = await env.DB.prepare("SELECT COUNT(DISTINCT ts/86400000) AS d FROM events WHERE user_id = ? AND ts >= ?").bind(userId, since).first<{ d: number }>();
      const byTopic: Record<string, { total: number; seen: number; known: number }> = {};
      for (const [, [, , t]] of Object.entries(CARD_META)) (byTopic[t] ??= { total: 0, seen: 0, known: 0 }).total++;
      for (const r of rs) { const t = CARD_META[r.card_id]?.[2]; if (t && byTopic[t]) { byTopic[t].seen++; if (r.level >= KNOWN_LEVEL) byTopic[t].known++; } }
      return {
        cards_total: total, cards_seen: rs.length, cards_known: rs.filter(r => r.level >= KNOWN_LEVEL).length,
        known_threshold_level: KNOWN_LEVEL, due_now: rs.filter(r => r.due_at <= now).length, never_seen: Math.max(0, total - rs.length),
        total_reviews: rs.reduce((a, r) => a + r.seen, 0), total_wrong: rs.reduce((a, r) => a + r.wrong, 0),
        last_7_days: { answers: ev?.n ?? 0, correct: ev?.ok ?? 0, accuracy: ev?.n ? Math.round((ev.ok / ev.n) * 100) / 100 : null, active_days_utc: days?.d ?? 0 },
        last_activity: ev?.last ? new Date(ev.last).toISOString() : (rs.length ? new Date(Math.max(...rs.map(r => r.last_seen))).toISOString() : null),
        by_topic: byTopic,
      };
    }
    case "get_struggling": {
      const limit = Math.min(Math.max(int(args?.limit) || 10, 1), 100);
      const rs = (await rows(env, userId)).filter(r => r.wrong > 0 || (r.seen > 0 && r.level === 0));
      rs.sort((a, b) => b.wrong - a.wrong || a.level - b.level || b.last_seen - a.last_seen);
      return { cards: rs.slice(0, limit).map(r => cardView(r, now)) };
    }
    case "get_due_cards": {
      const rs = (await rows(env, userId)).filter(r => r.seen > 0 && r.due_at <= now).sort((a, b) => a.due_at - b.due_at);
      const seenIds = new Set((await rows(env, userId)).filter(r => r.seen > 0).map(r => r.card_id));
      return { now: new Date(now).toISOString(), due_count: rs.length, cards: rs.map(r => cardView(r, now)),
        never_seen_count: Object.keys(CARD_META).filter(id => !seenIds.has(id)).length };
    }
    case "get_recent_activity": {
      const days = Math.min(Math.max(int(args?.days) || 7, 1), 90);
      const { results } = await env.DB.prepare("SELECT card_id, ok, ts FROM events WHERE user_id = ? AND ts >= ? AND type = 'answer' ORDER BY ts")
        .bind(userId, now - days * 864e5).all<{ card_id: string; ok: number; ts: number }>();
      const per: Record<string, { answers: number; correct: number; wrong_cards: Set<string>; cards: Set<string> }> = {};
      for (const e of results) {
        const d = new Date(e.ts).toISOString().slice(0, 10);
        const p = (per[d] ??= { answers: 0, correct: 0, wrong_cards: new Set(), cards: new Set() });
        p.answers++; p.correct += e.ok; p.cards.add(e.card_id); if (!e.ok) p.wrong_cards.add(e.card_id);
      }
      const label = (id: string) => ({ card_id: id, dutch: CARD_META[id]?.[0] ?? null, russian: CARD_META[id]?.[1] ?? null });
      return { days, total_answers: results.length, total_correct: results.reduce((a, e) => a + e.ok, 0), per_day_utc: Object.entries(per).map(([date, p]) => ({
        date, answers: p.answers, correct: p.correct, accuracy: Math.round((p.correct / p.answers) * 100) / 100,
        distinct_cards: p.cards.size, missed: [...p.wrong_cards].map(label) })) };
    }
    case "get_current_session": return currentSession(env, userId, now);
  }
  throw new RpcError(-32602, `Unknown tool: ${name}`);
}
type Ev = { card_id: string | null; type: string; ok: number | null; data: string | null; ts: number };
function evView(e: Ev) {
  const m = e.card_id ? CARD_META[e.card_id] : undefined;
  let data: unknown = null; try { data = e.data ? JSON.parse(e.data) : null; } catch { data = e.data; }
  return { ts: new Date(e.ts).toISOString(), type: e.type, card_id: e.card_id, dutch: m?.[0] ?? null, russian: m?.[1] ?? null,
    ...(e.type === "answer" ? { ok: !!e.ok } : {}), ...(data != null ? { data } : {}) };
}
async function currentSession(env: Env, userId: string, now: number) {
  // Walk back from the newest event in pages until a gap >= SESSION_GAP is found (cap 5000 events).
  const evs: Ev[] = [];
  let before = Number.MAX_SAFE_INTEGER, done = false;
  while (!done && evs.length < 5000) {
    const { results } = await env.DB.prepare("SELECT card_id, type, ok, data, ts FROM events WHERE user_id = ? AND ts < ? ORDER BY ts DESC, rowid DESC LIMIT 500")
      .bind(userId, before).all<Ev>();
    if (!results.length) break;
    for (const e of results) {
      const prev = evs.length ? evs[evs.length - 1].ts : null;
      if (prev !== null && prev - e.ts >= SESSION_GAP) { done = true; break; }
      evs.push(e);
    }
    if (results.length < 500) break;
    before = results[results.length - 1].ts;
  }
  if (!evs.length) return { session: null, message: "no events yet" };
  evs.reverse();
  const start = evs[0].ts, end = evs[evs.length - 1].ts;
  const answers = evs.filter(e => e.type === "answer");
  const last = [...evs].reverse().find(e => e.card_id);
  const cur = last?.card_id ? { card_id: last.card_id, dutch: CARD_META[last.card_id]?.[0] ?? null, russian: CARD_META[last.card_id]?.[1] ?? null } : null;
  return { session: {
    started_at: new Date(start).toISOString(), last_event_at: new Date(end).toISOString(),
    duration_minutes: Math.round((end - start) / 6000) / 10, active_now: now - end < 5 * 60000,
    minutes_since_last_event: Math.round((now - end) / 6000) / 10, current_card: cur,
    answers_right: answers.filter(e => e.ok).length, answers_wrong: answers.filter(e => !e.ok).length,
    flips: evs.filter(e => e.type === "flip").length, distinct_cards: new Set(evs.map(e => e.card_id).filter(Boolean)).size,
    event_count: evs.length, events: evs.slice(-300).map(evView), events_truncated: evs.length > 300 } };
}
class RpcError extends Error { constructor(public code: number, msg: string) { super(msg); } }

async function handleMcp(req: Request, env: Env): Promise<Response> {
  const origin = req.headers.get("Origin");
  if (origin && origin !== ALLOWED_ORIGIN) return json({ error: "origin not allowed" }, 403);
  if (req.method === "GET") return new Response("SSE stream not supported (stateless server)", { status: 405, headers: { Allow: "POST" } });
  if (req.method === "DELETE") return new Response(null, { status: 405, headers: { Allow: "POST" } });
  if (req.method !== "POST") return new Response(null, { status: 405, headers: { Allow: "POST" } });
  const userId = await authUser(env, req, "read");
  if (!userId) return json({ jsonrpc: "2.0", id: null, error: { code: -32001, message: "Unauthorized: read token required" } }, 401,
    { "WWW-Authenticate": 'Bearer realm="dutch-api"' });
  let msg: any;
  try { msg = await req.json(); } catch { return json({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } }, 400); }
  const batch = Array.isArray(msg);
  const msgs: any[] = batch ? msg : [msg];
  const out: any[] = [];
  for (const m of msgs) {
    if (!m || m.jsonrpc !== "2.0" || typeof m.method !== "string") {
      if (m && ("result" in m || "error" in m)) continue; // client responses: ignore
      out.push({ jsonrpc: "2.0", id: m?.id ?? null, error: { code: -32600, message: "Invalid Request" } }); continue;
    }
    if (m.id === undefined || m.id === null) continue; // notification (e.g. notifications/initialized)
    try {
      let result: unknown;
      switch (m.method) {
        case "initialize": {
          const v = m.params?.protocolVersion;
          result = { protocolVersion: PROTOCOL_VERSIONS.includes(v) ? v : PROTOCOL_VERSIONS[0],
            capabilities: { tools: { listChanged: false } },
            serverInfo: { name: "dutch-flashcards", version: "1.0.0" },
            instructions: "Read-only access to Pavel's Dutch flashcard progress. Levels 0-6; level >= 3 counts as known. Times are ISO UTC." };
          break;
        }
        case "ping": result = {}; break;
        case "tools/list": result = { tools: TOOLS }; break;
        case "tools/call": {
          const data = await callTool(env, userId, String(m.params?.name), m.params?.arguments ?? {});
          result = { content: [{ type: "text", text: JSON.stringify(data, null, 2) }], structuredContent: data, isError: false };
          break;
        }
        default: throw new RpcError(-32601, `Method not found: ${m.method}`);
      }
      out.push({ jsonrpc: "2.0", id: m.id, result });
    } catch (e: any) {
      out.push({ jsonrpc: "2.0", id: m.id, error: { code: e instanceof RpcError ? e.code : -32603, message: e?.message || "Internal error" } });
    }
  }
  if (!out.length) return new Response(null, { status: 202 });
  return json(batch ? out : out[0]);
}

// ---------- REST ----------
async function recentEvents(env: Env, userId: string, limit: number, since: number) {
  const { results } = await env.DB.prepare("SELECT card_id, type, ok, data, ts FROM events WHERE user_id = ? AND ts >= ? ORDER BY ts DESC, rowid DESC LIMIT ?")
    .bind(userId, since, limit).all<Ev>();
  return results.map(evView);
}

async function handleApi(req: Request, env: Env, path: string): Promise<Response> {
  if (req.method === "POST" && path === "/v1/register") {
    const id = crypto.randomUUID(), token = randomToken();
    await env.DB.prepare("INSERT INTO users (id, token_hash, created_at) VALUES (?, ?, ?)").bind(id, await sha256hex(token), Date.now()).run();
    return json({ userId: id, token });
  }
  if (req.method === "GET" && path === "/v1/stats") {
    const uid = (await authUser(env, req, "write")) ?? (await authUser(env, req, "read"));
    if (!uid) return json({ error: "unauthorized" }, 401);
    const now = Date.now();
    return json({ summary: await callTool(env, uid, "get_summary", {}), struggling: await callTool(env, uid, "get_struggling", { limit: 15 }),
      session: await currentSession(env, uid, now), recent_events: (await recentEvents(env, uid, 100, 0)) });
  }
  const userId = await authUser(env, req, "write");
  if (!userId) return json({ error: "unauthorized" }, 401);
  if (req.method === "GET" && path === "/v1/events") {
    const u = new URL(req.url);
    const limit = Math.min(Math.max(int(u.searchParams.get("limit")) || 100, 1), 1000);
    return json({ events: await recentEvents(env, userId, limit, int(u.searchParams.get("since"))) });
  }
  if (req.method === "GET" && path === "/v1/progress") return json({ userId, progress: await getProgress(env, userId), server_time: Date.now() });
  if (req.method === "POST" && (path === "/v1/sync" || path === "/v1/import")) {
    let body: any;
    try { body = await req.json(); } catch { return json({ error: "invalid json" }, 400); }
    const r = await applySync(env, userId, body);
    return json({ ok: true, ...r, progress: await getProgress(env, userId), server_time: Date.now() });
  }
  if (req.method === "POST" && path === "/v1/read-token") {
    const t = randomToken();
    await env.DB.prepare("UPDATE users SET read_token_hash = ? WHERE id = ?").bind(await sha256hex(t), userId).run();
    return json({ readToken: t });
  }
  return json({ error: "not found" }, 404);
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    const origin = req.headers.get("Origin");
    if (url.pathname === "/dashboard" && req.method === "GET") return dashboard();
    if (url.pathname === "/mcp") {
      try { return await handleMcp(req, env); } catch { return json({ error: "internal error" }, 500); }
    }
    if (req.method === "OPTIONS") {
      if (origin !== ALLOWED_ORIGIN) return new Response(null, { status: 403 });
      return new Response(null, { status: 204, headers: cors(origin) });
    }
    if (origin && origin !== ALLOWED_ORIGIN && origin !== url.origin) return json({ error: "origin not allowed" }, 403);
    let res: Response;
    try {
      res = url.pathname === "/" ? json({ name: "dutch-api", ok: true }) : await handleApi(req, env, url.pathname);
    } catch (e: any) {
      res = e instanceof HttpError ? json({ error: e.message }, e.status) : json({ error: "internal error" }, 500);
    }
    for (const [k, v] of Object.entries(cors(origin))) res.headers.set(k, v);
    return res;
  },
};

// ---------- dashboard (same-origin page; token kept in sessionStorage only) ----------
function dashboard(): Response {
  const nonce = randomToken();
  const html = DASHBOARD_HTML.replace(/__NONCE__/g, nonce);
  return new Response(html, { headers: {
    "Content-Type": "text/html; charset=utf-8",
    "Content-Security-Policy": `default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'`,
    "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer", "X-Frame-Options": "DENY", "Cache-Control": "no-store",
  } });
}
const DASHBOARD_HTML = `<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Dutch flashcards · dashboard</title><style nonce="__NONCE__">
body{font-family:system-ui,sans-serif;margin:16px;background:#f4f1ea;color:#222}h1{color:#c4561b;font-size:1.3rem}
section{background:#fff;border-radius:12px;padding:12px 16px;margin:12px 0;box-shadow:0 2px 8px rgba(0,0,0,.08)}
table{border-collapse:collapse;width:100%;font-size:.9rem}td,th{border-bottom:1px solid #eee;padding:4px 6px;text-align:left}
input{width:min(420px,90%);padding:8px}button{padding:8px 14px}.err{color:#c00}.kv span{display:inline-block;margin-right:18px}
</style></head><body><h1>🇳🇱 Dutch flashcards · dashboard</h1>
<section><label>Токен (код устройства или токен для Grok): <input id="tok" type="password" autocomplete="off"></label>
<button id="go">Показать</button> <button id="out">Выйти</button> <span id="msg"></span></section>
<div id="out-wrap" hidden><section><h2>Сводка</h2><div id="sum" class="kv"></div></section>
<section><h2>Текущая сессия</h2><div id="sess" class="kv"></div></section>
<section><h2>Трудные карточки</h2><table id="strug"></table></section>
<section><h2>Последние события</h2><table id="evs"></table></section></div>
<script nonce="__NONCE__">
const $=id=>document.getElementById(id);
$("tok").value=sessionStorage.getItem("dash-token")||"";
function row(t,cells,h){const tr=document.createElement("tr");for(const c of cells){const td=document.createElement(h?"th":"td");td.textContent=c==null?"":String(c);tr.appendChild(td);}t.appendChild(tr);}
function kv(el,o){el.textContent="";for(const[k,v]of Object.entries(o)){if(v&&typeof v==="object")continue;const s=document.createElement("span");s.textContent=k+": "+v;el.appendChild(s);}}
async function load(){const t=$("tok").value.trim();if(!t)return;sessionStorage.setItem("dash-token",t);$("msg").textContent="…";$("msg").className="";
 try{const r=await fetch("/v1/stats",{headers:{Authorization:"Bearer "+t}});if(!r.ok)throw new Error(r.status===401?"неверный токен":"HTTP "+r.status);
 const d=await r.json();kv($("sum"),d.summary);kv($("sess"),d.session.session||{сессия:"нет"});
 const cur=d.session.session&&d.session.session.current_card;if(cur){const s=document.createElement("span");s.textContent="текущая: "+cur.dutch+" — "+cur.russian;$("sess").appendChild(s);}
 const st=$("strug");st.textContent="";row(st,["карточка","перевод","тема","уровень","ошибок","показов"],1);for(const c of d.struggling.cards)row(st,[c.dutch,c.russian,c.topic,c.level,c.wrong,c.seen]);
 const ev=$("evs");ev.textContent="";row(ev,["время","тип","карточка","перевод","ok","data"],1);for(const e of d.recent_events)row(ev,[new Date(e.ts).toLocaleString(),e.type,e.dutch,e.russian,e.ok==null?"":(e.ok?"✓":"✗"),e.data==null?"":JSON.stringify(e.data)]);
 $("out-wrap").hidden=false;$("msg").textContent="обновлено "+new Date().toLocaleTimeString();
 }catch(e){$("msg").textContent=e.message;$("msg").className="err";}}
$("go").onclick=load;$("tok").onkeydown=e=>{if(e.key==="Enter")load();};
$("out").onclick=()=>{sessionStorage.removeItem("dash-token");$("tok").value="";$("out-wrap").hidden=true;};
if($("tok").value)load();setInterval(()=>{if(!document.hidden&&$("tok").value)load();},30000);
</script></body></html>`;
